<?php require_once __DIR__.'/config.php'; $me=require_login(); $message='';$error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf']??'')){$error='Invalid security token.';}elseif(isset($_POST['save_profile'])){$chat->updateProfile((int)$me['id'],$_POST['name']??$me['name'],$_POST['about']??$me['about']);$message='Profile updated.';}elseif(isset($_POST['change_password'])){[$ok,$msg]=$chat->changePassword((int)$me['id'],$_POST['old_password']??'',$_POST['new_password']??'');$ok?$message=$msg:$error=$msg;}elseif(isset($_POST['avatar']) && isset($_FILES['avatar'])){$f=$_FILES['avatar'];if($f['error']===UPLOAD_ERR_OK && $f['size']<=3*1024*1024){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(isset($allowed[$mime])){$dir=__DIR__.'/uploads/avatars';if(!is_dir($dir))mkdir($dir,0775,true);$name='avatar_'.(int)$me['id'].'_'.time().'.'.$allowed[$mime];move_uploaded_file($f['tmp_name'],$dir.'/'.$name);$chat->saveAvatar((int)$me['id'],'uploads/avatars/'.$name);$message='Profile photo updated.';}else $error='Use JPG, PNG or WebP.';}else $error='Photo is too large or failed to upload.';}$me=$chat->currentUser();} ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Profile — WhatsApp Clone</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="auth.css"></head><body><div class="settings-page"><header class="settings-header"><a href="index.php">‹</a><h1>Profile & settings</h1></header><main class="settings-card"><?php if($message):?><div class="alert success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><div class="profile-photo"><div class="big-avatar"><?php if($me['avatar']):?><img src="<?=e($me['avatar'])?>"><?php else:?><?=e(mb_strtoupper(mb_substr($me['name'],0,1)))?><?php endif;?></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="file" name="avatar" accept="image/jpeg,image/png,image/webp" onchange="this.form.submit()"><input type="hidden" name="avatar" value="1"></form></div><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="save_profile" value="1"><div class="field"><label>Name</label><input name="name" required value="<?=e($me['name'])?>"></div><div class="field"><label>Phone</label><input value="<?=e($me['phone'])?>" disabled></div><div class="field"><label>About</label><input name="about" maxlength="255" value="<?=e($me['about'])?>"></div><button class="primary">Save profile</button></form><hr><h2>Change password</h2><form method="post" class="settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="change_password" value="1"><div class="field"><label>Current password</label><input type="password" name="old_password" required></div><div class="field"><label>New password</label><input type="password" name="new_password" minlength="6" required></div><button class="primary">Change password</button></form><form method="post" action="logout.php" class="logout-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button>Log out</button></form></main></div></body></html>
